const a = $input.first().json.body || $input.first().json;
const type = a.alert_type || 'UNKNOWN';
const details = typeof a.details === 'string' ? a.details : (a.details?.message || JSON.stringify(a.details || ''));
const action = a.action_taken || '';
const critical = ['CIRCUIT_BREAKER','DRAWDOWN_LIMIT','MODEL_CONFIDENCE_COLLAPSE'].includes(type);
const emoji = critical ? '\uD83D\uDEA8' : '\u26A0\uFE0F';
const ping = critical ? '@everyone ' : '';
const ts = new Date().toISOString().replace('T',' ').substring(0,19) + ' UTC';
const msg = ping + emoji + ' **' + type + '** \u2014 ' + ts + '\n' + details + '\nAction: ' + action;
return [{ json: { message: msg, critical, type } }];
